static void check(bool v,const char* s){if(!v)throw std::runtime_error(s);}
static std::wstring widen(const std::string& s){return {s.begin(),s.end()};}
static uint64_t decimal(const char* s){check(s&&*s,"numeric handle");uint64_t v=0;for(;*s;++s){check(*s>='0'&&*s<='9',"numeric character");unsigned d=static_cast<unsigned>(*s-'0');check(v<=(UINT64_MAX-d)/10,"numeric overflow");v=v*10+d;}return v;}
static void integer(std::vector<uint8_t>& b,uint64_t v,unsigned n){for(unsigned i=n;i>0;--i)b.push_back(static_cast<uint8_t>(v>>(8*(i-1))));}
static uint64_t integer(const std::vector<uint8_t>& b,size_t& at,unsigned n){check(at+n<=b.size(),"bootstrap truncation");uint64_t v=0;while(n--)v=(v<<8)|b[at++];return v;}
static void exact(std::shared_ptr<Pipe> pipe,bool write,uint8_t* bytes,size_t n,Clock::time_point end){size_t at=0;while(at<n){size_t done=0;auto rc=write?pipe->write(bytes+at,std::min<size_t>(32,n-at),done,end):pipe->read(bytes+at,std::min<size_t>(32,n-at),done,end);check(rc==Error::None&&done>0,"bootstrap finite IO");at+=done;}}
