static void send_boot(std::shared_ptr<Pipe> p,const Bootstrap& x,Clock::time_point end){std::vector<uint8_t> b;for(char c:std::string("S1BOOT01"))b.push_back(static_cast<uint8_t>(c));integer(b,120,4);integer(b,x.parent,4);integer(b,x.child,4);integer(b,x.side,4);integer(b,x.manifest_handle,8);integer(b,x.parent_handle,8);integer(b,x.parent_birth,8);integer(b,x.run,8);integer(b,x.file.volume,4);integer(b,x.file.high,4);integer(b,x.file.low,4);check(x.sha.size()==64,"bootstrap hash");b.insert(b.end(),x.sha.begin(),x.sha.end());check(b.size()==132,"bootstrap independent size");exact(p,true,b.data(),b.size(),end);}
