    auto channel=std::make_shared<Channel>(pipe,q.local,Direction::Endpoint,end,7);auto port=std::make_shared<Port>(channel,q.local,true);
    {Client client(module.keepalive(),port,end);auto getter=module.function<GetRunApi>("ns_consumer_get_run_api");check(client.bind(getter,Module::owns,module.handle())==NS_OK,"owned V2 functions");NS_RunApi probe{};check(getter(NS_RUN_VERSION,sizeof(probe),&probe)==NS_OK,"wrapped API");auto fault=q;fault.reserved=0x53544658u;auto callback=port->callbacks();NS_RunHandle* rejected=nullptr;check(probe.create(&fault,&callback,&rejected)==NS_STATE&&!rejected,"origin badalloc contained in actual V2 thunk");std::puts("C_POD_ORIGIN_EXCEPTION_PROBE status_only=1 foreign_unwind=0");check(client.create(q)==NS_OK,"full request create");NS_RunResult out{};const int rc=client.execute(out);check(rc==NS_OK&&out.phase==4,"fixture V2 completion");auto drop=module.function<int32_t(*)()>("ns_control_drop_all_callbacks");check(drop()==NS_OK&&port->acknowledge_fixture_no_more_callbacks(),"controlled producer last-ref acknowledgement");}
