        Handle output(CreateFileA((root+"/"+std::to_string(side)+".out").c_str(),GENERIC_WRITE,FILE_SHARE_READ,&sa,CREATE_NEW,FILE_ATTRIBUTE_NORMAL,nullptr));Handle error(CreateFileA((root+"/"+std::to_string(side)+".err").c_str(),GENERIC_WRITE,FILE_SHARE_READ,&sa,CREATE_NEW,FILE_ATTRIBUTE_NORMAL,nullptr));Handle input(CreateFileW(L"NUL",GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE,&sa,OPEN_EXISTING,0,nullptr));check(output.value!=INVALID_HANDLE_VALUE&&error.value!=INVALID_HANDLE_VALUE&&input.value!=INVALID_HANDLE_VALUE,"owned child logs");
        HANDLE inherited[]={pipe,output.value,error.value,input.value};SIZE_T bytes=0;InitializeProcThreadAttributeList(nullptr,1,0,&bytes);std::vector<uint8_t> memory(bytes);auto* attrs=reinterpret_cast<LPPROC_THREAD_ATTRIBUTE_LIST>(memory.data());check(InitializeProcThreadAttributeList(attrs,1,0,&bytes)!=0,"attribute list");
