        check(CreateProcessW(widen(image.path()).c_str(),cmd.data(),nullptr,nullptr,TRUE,CREATE_SUSPENDED|CREATE_NO_WINDOW|EXTENDED_STARTUPINFO_PRESENT,nullptr,nullptr,&start.StartupInfo,&info)!=0,"owned suspended child");process=Handle(info.hProcess);thread=Handle(info.hThread);pid=info.dwProcessId;birth=creation_time(process.value);CloseHandle(pipe);endpoint={};
