static Deployment make_record(const LockedFile& image,const std::string& module,const std::string& module_sha,DWORD a,DWORD b){Deployment d;d.fields={"S1HANDOFF1","HOST_NONBUSINESS_FIXTURE","0102030405060708",std::to_string(GetCurrentProcessId()),image.path(),image.sha(4*1048576,Clock::now()+std::chrono::seconds(3)),module,module_sha,"host.handoff.fixture","151",NS_PACKAGE,"com.kaihong.mdds.handoff","5000",std::to_string(a),"3e01ff55454d202020104033bf453b00","100","host-a","fixture-network-a","1","com.kaihong.mdds.handoff.a",std::to_string(b),"3e01ff55454d202020104433991c3b00","101","host-b","fixture-network-b","2","com.kaihong.mdds.handoff.b"};return d;}
struct Controller {
    stage1_run::Window window;std::shared_ptr<Channel> channels[2];std::mutex gate;bool released[5]{};std::atomic<bool> ok{true};std::atomic<unsigned> done{0};
    Controller(NS_Envelope a,NS_Envelope b,Clock::time_point end):window(a,b,end,true){}
    void run(unsigned side){try{for(;;){Frame f;if(channels[side]->receive(f)!=Error::None)throw std::runtime_error("controller read");std::lock_guard<std::mutex> l(gate);check(f.kind==Kind::Event&&window.emit(f.event),"controller envelope/order/transcript");for(uint32_t stage:{1u,2u,4u,3u})if(!released[stage]&&window.can_release(stage)){Frame token;token.kind=Kind::Release;token.release=stage;check(channels[0]->send(token)==Error::None&&channels[1]->send(token)==Error::None,"controller releases");released[stage]=true;}if(f.event.kind==NS_TEARDOWN)break;}}catch(...){ok=false;cancel();}++done;}
    void cancel(){window.cancel();for(auto& c:channels)if(c)c->cancel();}
};
static std::string read_log(const std::string& path){std::ifstream in(path,std::ios::binary);std::ostringstream out;out<<in.rdbuf();check(out.str().size()<=65536,"child log bound");return out.str();}
static bool finish_threads(std::thread& a,std::thread& b){HANDLE threads[2]{};DWORD count=0;if(a.joinable())threads[count++]=a.native_handle();if(b.joinable())threads[count++]=b.native_handle();const bool ended=!count||WaitForMultipleObjects(count,threads,TRUE,2000)==WAIT_OBJECT_0;for(auto* t:{&a,&b})if(t->joinable()){if(ended)t->join();else t->detach();}return ended;}
